import java.util.HashMap;
import java.util.Map;

public class Main {
    public static void main(String[] args) {
        String template = "This is a new {object} at {place}";
        Map<String, String> map = new HashMap<>();
        map.put("object", "student");
        map.put("place", "point 3, 4");

        String result = replaceString(template, map);
        System.out.println(result);
    }

    public static String replaceString(String template, Map<String, String> map) {
        StringBuilder sb = new StringBuilder(template);
        for (Map.Entry<String, String> entry : map.entrySet()) {
            sb.replace(sb.indexOf("{" + entry.getKey() + "}", 0), sb.indexOf("{" + entry.getKey() + "}" + "}"), entry.getValue());
        }
        return sb.toString();
    }
}
```

