import java.util.HashMap;
import java.util.Map;

public class Main {
    public static void main(String[] args) {
        String template = "This is a new {object} at {place}";
        Map<String, String> map = new HashMap<>();
        map.put("object", "student");
        map.put("place", "point 3, 4");

        String result = replaceString(template, map);
        System.out.println(result);
    }

    public static String replaceString(String template, Map<String, String> map) {
        return String.format(template, map.values().toArray());
    }
}
